#define PS2_TOOLS_ASSET "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width\"><title>PS2 — Devices and source code</title><style>body{max-width:960px;margin:30px auto;padding:16px;background:#101b2e;color:#eef;font:16px system-ui}button,input,select{font:inherit;padding:10px;margin:8px}pre,textarea{white-space:pre-wrap;overflow-wrap:anywhere;background:#07101f;color:#eef;padding:16px;border:1px solid #345;border-radius:12px}textarea{box-sizing:border-box;width:100%;font:15px monospace}a{color:#8df}</style><h1>PS2 devices and background code</h1><a href=\"/\">Back to control panel</a><h2>Attached devices</h2><button id=\"refresh\">Scan USB tree</button><button id=\"relay-recover\">Re-detect unavailable relay board</button><label>USB device ID <input id=\"usb-id\" type=\"number\" min=\"1\" max=\"31\" value=\"1\"></label><button id=\"detail\">Raw descriptors / endpoints</button><pre id=\"devices\">Not scanned yet.</pre><h2>C++ / MIPS assembly</h2><p>Source is sent directly to the PS2. Compilation and real MIPS execution happen on the console; no PC compiler is needed.</p><p>C++ statement subset: int/bool, arithmetic/comparison, if/else, while, return, print, millis, yield_ms. No classes, templates, STL or includes. Assembly: li, move, addu/subu, bitwise operations, shifts, lw/sw/lb/lbu/sb, mult/mflo/mfhi, b/beq/bne, print, text, ret, .word. Branch delay slots get a nop. s0/s1 and the stack frame are reserved for the runtime.</p><p>3072 source bytes, 2-second time limit. Gamepad has higher priority. Native code has no memory protection; invalid memory access or disabling interrupts can hang the console.</p><select id=\"lang\"><option value=\"cpp\">C++ statement subset</option><option value=\"asm\">MIPS assembly</option></select><button id=\"sample\">Sample code</button><input id=\"source-file\" type=\"file\" accept=\".cpp,.cc,.c,.s,.S,.asm,.txt\"><textarea id=\"source\" rows=\"13\" spellcheck=\"false\">int main() {\n  int a = 6;\n  print(\"PS2 result: \");\n  print(a * 7);\n  return a * 7;\n}</textarea><button id=\"run\">Compile and run on PS2</button><button id=\"status\">Read status</button><button id=\"cancel\">Cancel job</button><pre id=\"job\">Ready.</pre><script>\nconst $=s=>document.querySelector(s);let timer;\nasync function req(p,b){let r=await fetch(p,{method:b===undefined?'GET':'POST',headers:b===undefined?{}:{'X-PS2-Exec':'1','Content-Type':'text/plain; charset=utf-8'},body:b,signal:AbortSignal.timeout(15000)}),t=await r.text();if(!r.ok)throw Error(r.status+' '+t);return JSON.parse(t)}\nasync function state(){let j=await req('/exec/status');$('#job').textContent=JSON.stringify({...j,stateName:['Ready','Uploading','Compiling / running','Completed','Timed out','Cancelled','Error','Compile error'][j.state]},null,2);return j}\n$('#status').onclick=()=>state().catch(e=>$('#job').textContent=e.message);\n$('#cancel').onclick=async()=>{try{await req('/exec/cancel','');await state()}catch(e){$('#job').textContent=e.message}};\n$('#run').onclick=async()=>{try{let source=$('#source').value;if(new TextEncoder().encode(source).length>3072)throw Error('Kaynak en fazla 3072 bytes');$('#run').disabled=true;await req('/exec/source?lang='+$('#lang').value,source);clearInterval(timer);timer=setInterval(async()=>{try{let j=await state();if(j.state!==2)clearInterval(timer)}catch(e){clearInterval(timer);$('#job').textContent=e.message}},500)}catch(e){$('#job').textContent=e.message}finally{$('#run').disabled=false}};\n$('#sample').onclick=()=>$('#source').value=$('#lang').value==='asm'?'text \"PS2 MIPS: \"\\nli $v0, 42\\nprint $v0\\nli $v0, 42\\nret':'int main() { int a = 6; print(a * 7); return a * 7; }';\n$('#source-file').onchange=async()=>{let f=$('#source-file').files[0];if(f){$('#source').value=await f.text();$('#lang').value=/\\.(s|asm)$/i.test(f.name)?'asm':'cpp'}};\nasync function scan(refresh){try{let d=await req(refresh?'/devices/refresh':'/devices');$('#devices').textContent=JSON.stringify(d,null,2);if(d.scanning)setTimeout(()=>scan(false),750)}catch(e){$('#devices').textContent=e.message}}\n$('#detail').onclick=async()=>{try{$('#devices').textContent=JSON.stringify(await req('/?usb='+Number($('#usb-id').value)),null,2)}catch(e){$('#devices').textContent=e.message}};\n$('#relay-recover').onclick=async()=>{try{$('#devices').textContent=JSON.stringify(await req('/relay/recover',''),null,2)}catch(e){$('#devices').textContent=e.message}};$('#refresh').onclick=()=>scan(true);state().catch(()=>{});\n</script></html>\r\n"
